import{_ as d,o as a,c as e,a5 as s}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"LinkedHashMap 和 HashMap","description":"","frontmatter":{"title":"`LinkedHashMap` 和 `HashMap`","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/04-Map/`LinkedHashMap` 和 `HashMap`.md","filePath":"posts/java快速入门/第三部分：核心 API/04-Map/`LinkedHashMap` 和 `HashMap`.md"}'),r={name:"posts/java快速入门/第三部分：核心 API/04-Map/`LinkedHashMap` 和 `HashMap`.md"};function o(p,t,n,i,h,l){return a(),e("div",null,[...t[0]||(t[0]=[s('<div><p><code>LinkedHashMap</code> 和 <code>HashMap</code> 是 Java 中两种常用的映射类型，都实现了 <code>Map</code> 接口，但它们在内部结构和行为上有一些重要的区别。下面是一个表格，详细比较这两者的特点：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>特性</td><td>HashMap</td><td>LinkedHashMap</td></tr><tr><td>排序</td><td>不保证任何顺序</td><td>按插入顺序或访问顺序维护键值对</td></tr><tr><td>性能</td><td>插入和查找的速度略快</td><td>插入和查找速度略慢，因为需要维护元素的顺序</td></tr><tr><td>内存占用</td><td>较低</td><td>较高，因为需要额外的内存来维护元素的顺序链表</td></tr><tr><td>迭代顺序</td><td>不固定，与键的哈希码有关</td><td>固定，按照元素的插入顺序或最后访问顺序（取决于构造时的选择）</td></tr><tr><td>构造函数选项</td><td>无特定选项</td><td>可以选择访问顺序（access-order）或插入顺序（insertion-order）</td></tr><tr><td>使用场景</td><td>当元素的顺序不重要时使用</td><td>当需要维持元素的插入顺序或访问顺序时使用</td></tr><tr><td>数据结构</td><td>基于哈希表的实现</td><td>基于哈希表的实现，但增加了一个双向链表以维护顺序</td></tr><tr><td>对null键和值的支持</td><td>允许键和值为null（最多一个null键）</td><td>同样允许键和值为null</td></tr></tbody></table><h3 id="总结" tabindex="-1">总结： <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结：&quot;">​</a></h3><ul><li><strong>使用 <code>HashMap</code></strong>：当你不需要关心 Map 中元素的顺序，只需要快速存取时。</li><li><strong>使用 <code>LinkedHashMap</code></strong>：当你需要保持元素插入的顺序，或者在 LRU 缓存（最近最少使用缓存）实现中保持访问顺序时。</li></ul><p><code>LinkedHashMap</code> 提供的顺序性使其在需要顺序的场景下非常有用，如在缓存策略、记录插入顺序的特定应用中，或者当输出的顺序需要与输入完全一致时。</p></div>',1)])])}const M=d(r,[["render",o]]);export{_ as __pageData,M as default};
